/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const tableName = event.payload.item.id;
	return {
		propName: 'selectedInputTable',
		value: tableName
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		eventName: 'SN_NS_ADMIN_INPUT_VALUE_CHANGED',
		eventPayload: {
			variableName: 'input_table',
			variableValue: event.payload.item.id
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: 'selectedTableFields',
		value: []
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let value = event.payload.value;
	if (value) {
		value = value.map(field => field.id).join(',');
	}
	return {
		eventName: 'SN_NS_ADMIN_INPUT_VALUE_CHANGED',
		eventPayload: {
			variableName: 'input_fields',
			variableValue: value || ''
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const fields = event.payload.value;
	debugger;
	return {
		propName: 'selectedTableFields',
		value: fields
	};
}
